#include "powder/plant.hpp"
#include <iostream>
#include <sstream>
#include <chrono>
#include <iomanip>
int main(int argc,char**argv){try{
 if(argc<7)throw std::runtime_error("plant_bench data checkpoint-or-initial phase split steps output-prefix");
 auto d=powder::read_plant_data(std::string(argv[1])+"/runtime.plant");d[4].x=float(std::stoi(argv[3]));powder::solve_plant_pressure(d,powder::read_plant_routes(std::string(argv[1])+"/runtime.routes"),1000);
 std::ifstream f(std::string(argv[1])+"/test_charge.csv");std::string line;std::getline(f,line);std::vector<powder::Grain> initial;
 while(std::getline(f,line)){std::replace(line.begin(),line.end(),',',' ');std::istringstream row(line);unsigned id,type;std::string supplier;float x,y,z,r,rho;if(!(row>>id>>type>>supplier>>x>>y>>z>>r>>rho)||id!=initial.size())throw std::runtime_error("charge");initial.push_back({x,y,z,float(type)});}
 auto positions=initial;std::vector<powder::Grain> velocity(initial.size());if(std::string(argv[2])!="initial"){std::ifstream checkpoint(argv[2],std::ios::binary);std::uint32_t n=0;checkpoint.read(reinterpret_cast<char*>(&n),4);if(n!=positions.size())throw std::runtime_error("count");checkpoint.read(reinterpret_cast<char*>(positions.data()),n*sizeof(powder::Grain));checkpoint.read(reinterpret_cast<char*>(velocity.data()),n*sizeof(powder::Grain));if(!checkpoint)throw std::runtime_error("checkpoint");}
 powder::GranularConfig c;c.plant=true;c.plant_triangle_fast=argc>7&&std::stoi(argv[7])!=0;c.plant_threaded=argc>8&&std::stoi(argv[8])!=0;c.kernel_optimize=true;c.profile=true;c.profile_split=std::stoi(argv[4])!=0;c.plant_data=d;c.count=unsigned(initial.size());c.radius=.00125f;c.dt=.00001f;c.iterations=8;
 powder::GranularGPU gpu(c,initial,std::vector<powder::Grain>(initial.size()));gpu.set_state(positions,velocity);gpu.advance(32,15,false);gpu.set_state(positions,velocity);auto before=gpu.timing();auto begin=std::chrono::steady_clock::now();unsigned steps=unsigned(std::stoul(argv[5]));for(unsigned i=0;i<steps;i+=16)gpu.advance(std::min(16u,steps-i),15,false);double wall=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();auto after=gpu.timing();for(int i=0;i<17;++i){after.gpu_seconds[i]-=before.gpu_seconds[i];after.calls[i]-=before.calls[i];}
 after.advance_wall-=before.advance_wall;after.submit_wall-=before.submit_wall;after.guard_wait_wall-=before.guard_wait_wall;after.profile_collect_wall-=before.profile_collect_wall;after.advance_thread_cpu-=before.advance_thread_cpu;after.submit_thread_cpu-=before.submit_thread_cpu;after.gpu_batch_span-=before.gpu_batch_span;after.gpu_intercommand_gap-=before.gpu_intercommand_gap;
 auto p=gpu.snapshot(),v=gpu.velocity_snapshot();unsigned counts[3]{};for(auto a:p){if(a.w<0||a.w>2)throw std::runtime_error("species");++counts[int(a.w)];}for(auto n:counts)if(n!=10000)throw std::runtime_error("count changed");std::ofstream b(std::string(argv[6])+".bin",std::ios::binary);if(!b)throw std::runtime_error("output binary cannot open");std::uint32_t n=unsigned(p.size());b.write(reinterpret_cast<char*>(&n),4);b.write(reinterpret_cast<const char*>(p.data()),p.size()*sizeof(powder::Grain));b.write(reinterpret_cast<const char*>(v.data()),v.size()*sizeof(powder::Grain));
 std::ofstream o(std::string(argv[6])+".json");if(!o)throw std::runtime_error("output JSON cannot open");o<<std::setprecision(12)<<"{\"count\":"<<n<<",\"steps\":"<<steps<<",\"wall_s\":"<<wall<<",\"rate\":"<<steps*c.dt/wall<<",\"timing\":";powder::write_granular_timing(o,after);o<<"}";std::cout<<"PASS "<<argv[6]<<" wall="<<wall<<" rate="<<steps*c.dt/wall<<std::endl;return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
